"""
Algorithm 2 — Exact success density of an m-sample record (Jordan's totient).

A record of numerators k_1..k_m recovers the order r exactly when
gcd(gcd(k_1..k_m), r) = 1.  The number of such records among all r^m is Jordan's
totient

    J_m(r) = sum_{d | r} mu(d) (r/d)^m = r^m prod_{p | r} (1 - p^-m),

so the success probability is exactly prod_{p | r} (1 - p^-m).  This module
computes the count in three independent ways (brute force, Moebius sum, Euler
product) and cross-checks them.
"""

from __future__ import annotations

from fractions import Fraction
from itertools import product
from math import gcd, isqrt
from typing import Iterable, List


def prime_factors(n: int) -> List[int]:
    out, d = [], 2
    while d * d <= n:
        if n % d == 0:
            out.append(d)
            while n % d == 0:
                n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        out.append(n)
    return out


def moebius(n: int) -> int:
    if n == 1:
        return 1
    m, mu = n, 1
    for p in prime_factors(n):
        m //= p
        if m % p == 0:
            return 0
        mu = -mu
    return mu


def divisors(n: int) -> List[int]:
    small = [d for d in range(1, isqrt(n) + 1) if n % d == 0]
    return small + [n // d for d in reversed(small) if n // d != d]


def record_gcd(ks: Iterable[int]) -> int:
    acc = 0
    for k in ks:
        acc = gcd(acc, k)
    return acc


def good_records_bruteforce(r: int, m: int) -> int:
    """Enumerate r^m records; exponential, used only as ground truth."""
    return sum(1 for ks in product(range(r), repeat=m)
               if gcd(record_gcd(ks), r) == 1)


def jordan_moebius(r: int, m: int) -> int:
    """J_m(r) by Moebius inversion.  Cost: O(sigma_0(r)) with factorisation."""
    return sum(moebius(d) * (r // d) ** m for d in divisors(r))


def jordan_euler(r: int, m: int) -> Fraction:
    """J_m(r) by the Euler product.  Cost: O(omega(r)) after factorisation."""
    val = Fraction(r ** m)
    for p in prime_factors(r):
        val *= 1 - Fraction(1, p ** m)
    return val


def success_probability(r: int, m: int) -> Fraction:
    """Exact probability that m uniform numerators recover the order r."""
    p = Fraction(1)
    for q in prime_factors(r):
        p *= 1 - Fraction(1, q ** m)
    return p


def demo() -> None:
    print(f"{'r':>7} {'m':>3} {'brute':>10} {'moebius':>10} {'euler':>10} {'prob':>10}")
    for r in (6, 12, 30):
        for m in (1, 2, 3):
            bf = good_records_bruteforce(r, m)
            mo = jordan_moebius(r, m)
            eu = jordan_euler(r, m)
            assert bf == mo == eu
            print(f"{r:>7} {m:>3} {bf:>10} {mo:>10} {str(eu):>10} "
                  f"{float(success_probability(r, m)):>10.6f}")
    # large orders: only the closed forms are feasible
    for r in (2 ** 31 - 1, 30030, 2 * 3 * 5 * 7 * 11 * 13 * 17 * 19):
        print(f"r={r:12d}  m=2 -> success probability "
              f"{float(success_probability(r, 2)):.8f}  "
              f"(uniform bound 0.5)")


if __name__ == "__main__":
    demo()
